<?php
require_once __DIR__.'/config/app.php';require_login();$uid=(int)$_SESSION['user_id'];$search=trim($_GET['search']??'');$type=trim($_GET['type']??'');$category=trim($_GET['category']??'');
$sql='SELECT items.*,users.full_name FROM items INNER JOIN users ON users.id=items.user_id WHERE items.status="active"';$params=[];$types='';
if($search!==''){$sql.=' AND (items.item_name LIKE ? OR items.description LIKE ? OR items.location LIKE ?)';$term='%'.$search.'%';$params[]=&$term;$params[]=&$term;$params[]=&$term;$types.='sss';}
if(in_array($type,['lost','found'],true)){$sql.=' AND items.type=?';$params[]=&$type;$types.='s';}
if($category!==''&&valid_category($category)){$sql.=' AND items.category=?';$params[]=&$category;$types.='s';}$sql.=' ORDER BY items.created_at DESC';$stmt=mysqli_prepare($conn,$sql);if($types!=='')mysqli_stmt_bind_param($stmt,$types,...$params);mysqli_stmt_execute($stmt);$result=mysqli_stmt_get_result($stmt);
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Search Items - UniFind</title><link rel="stylesheet" href="css/style.css"></head><body><nav class="navbar"><a class="brand" href="dashboard.php">UniFind</a><div class="nav-actions"><a class="nav-link" href="my-claims.php">My Claims</a><a class="btn btn-small btn-secondary" href="dashboard.php">Dashboard</a><a class="btn btn-small" href="logout.php">Logout</a></div></nav><main class="page-container"><section class="page-heading"><div><span class="eyebrow">Explore Reports</span><h1>Search Lost & Found Items</h1><p>Use keywords, type and category to narrow the results.</p></div></section><form class="filter-bar" method="get"><input name="search" placeholder="Search item, description or location..." value="<?=e($search)?>"><select name="type"><option value="">All Types</option><option value="lost" <?=$type==='lost'?'selected':''?>>Lost</option><option value="found" <?=$type==='found'?'selected':''?>>Found</option></select><select name="category"><option value="">All Categories</option><?php foreach(get_categories() as $c):?><option value="<?=e($c)?>" <?=$category===$c?'selected':''?>><?=e($c)?></option><?php endforeach;?></select><button class="btn">Search</button><a class="btn btn-secondary" href="search-items.php">Reset</a></form><?php if(mysqli_num_rows($result)):?><section class="item-grid"><?php while($i=mysqli_fetch_assoc($result)):?><article class="item-card"><?php if($i['image']&&is_file(__DIR__.'/uploads/'.$i['image'])):?><img class="item-image" src="uploads/<?=e($i['image'])?>" alt=""><?php else:?><div class="item-image placeholder">No Image Available</div><?php endif;?><div class="item-card-body"><div class="card-topline"><span class="status-pill <?=$i['type']==='lost'?'lost-pill':'found-pill'?>"><?=strtoupper(e($i['type']))?></span><span class="small-muted"><?=e($i['item_date'])?></span></div><h3><?=e($i['item_name'])?></h3><p class="item-description"><?=e($i['description'])?></p><div class="detail-list"><span><strong>Category:</strong> <?=e($i['category'])?></span><span><strong>Location:</strong> <?=e($i['location'])?></span><span><strong>Reported by:</strong> <?=e($i['full_name'])?></span></div><?php if($i['type']==='found'):?><?php if((int)$i['user_id']===$uid):?><span class="status-pill neutral-pill">YOUR REPORT</span><?php else:?><a class="btn btn-block" href="claim-item.php?id=<?=(int)$i['id']?>">Claim Item</a><?php endif;?><?php endif;?></div></article><?php endwhile;?></section><?php else:?><div class="empty-state"><h3>No items found</h3><p>Try another keyword or reset the filters.</p></div><?php endif;?></main><script src="js/ui-effects.js"></script></body></html>